// internal/sync/mutex.go (Go 1.27.1)
func (m *Mutex) Lock() {
	// Fast path: grab unlocked mutex.
	if atomic.CompareAndSwapInt32(&m.state, 0, mutexLocked) {
		if race.Enabled {
			race.Acquire(unsafe.Pointer(m))
		}
		return
	}
	// Slow path (outlined so that the fast path can be inlined)
	m.lockSlow()
}

// An AI assistant's comment: "Pooling the buffer makes render allocation free."
var bufPool = sync.Pool{New: func() any { return make([]byte, 0, 1024) }}

func render(name string) int {
	buf := bufPool.Get().([]byte)
	buf = append(buf[:0], "hello "...)
	buf = append(buf, name...)
	n := len(buf)
	bufPool.Put(buf)
	return n
}

// measured with testing.AllocsPerRun(100, func() { render("x") })

func sumEveryFourth(s []int) int {
	var total int
	for i := 0; i+3 < len(s); i += 4 {
		total += s[i] + s[i+1] + s[i+2] + s[i+3]
	}
	return total
}
