// An AI assistant's pooled renderer.
var bufPool = sync.Pool{New: func() any { return new(bytes.Buffer) }}

func render(name string) []byte {
	buf := bufPool.Get().(*bytes.Buffer)
	buf.WriteString("hello ")
	buf.WriteString(name)
	out := buf.Bytes()
	bufPool.Put(buf)
	return out
}

